                  \x3c!-- ================= 3. 中央破碎的主祭坛 ================= --\x3e
                  \x3c!-- 祭坛主体 (不规则的残破多边形) --\x3e
                  <polygon points="450,100 700,180 850,450 780,750 550,880 250,800 150,500 280,200" fill="#18181b" stroke="#3f3f46" stroke-width="4" filter="drop-shadow(0px 30px 30px rgba(0,0,0,0.9))"/>

                  \x3c!-- 祭坛地面的暗色几何刻痕 --\x3e
                  <polygon points="450,150 650,220 780,450 720,700 550,800 300,720 220,500 320,250" fill="none" stroke="#27272a" stroke-width="2"/>

                  \x3c!-- ================= 4. 撕裂祭坛的岩浆/血色裂缝 ================= --\x3e
                  \x3c!-- 裂缝的光晕层 --\x3e
                  <path d="M 500 500 L 350 300 L 250 200 M 500 500 L 700 400 L 850 350 M 500 500 L 600 700 L 750 850 M 500 500 L 300 650 L 200 800 M 350 300 L 450 150 M 600 700 L 400 900" stroke="#991b1b" stroke-width="15" fill="none" filter="blur(8px)"/>
                  \x3c!-- 裂缝的炽热层 --\x3e
                  <path d="M 500 500 L 350 300 L 250 200 M 500 500 L 700 400 L 850 350 M 500 500 L 600 700 L 750 850 M 500 500 L 300 650 L 200 800 M 350 300 L 450 150 M 600 700 L 400 900" stroke="#dc2626" stroke-width="6" fill="none" filter="blur(2px)"/>
                  \x3c!-- 裂缝的极高温核心 (撕裂感) --\x3e
                  <path d="M 500 500 L 350 300 L 250 200 M 500 500 L 700 400 L 850 350 M 500 500 L 600 700 L 750 850 M 500 500 L 300 650 L 200 800 M 350 300 L 450 150 M 600 700 L 400 900" stroke="#fca5a5" stroke-width="1.5" fill="none"/>

                  \x3c!-- ================= 5. 古老且断裂的血色阵纹 (残破的规则) ================= --\x3e
                  \x3c!-- 断裂的外环阵法 --\x3e
                  <circle cx="500" cy="500" r="320" fill="none" stroke="#dc2626" stroke-width="3" stroke-dasharray="40 100 200 80 10 50" opacity="0.6"/>
                  <circle cx="500" cy="500" r="300" fill="none" stroke="#ef4444" stroke-width="1" stroke-dasharray="10 30 50 150 20 60" opacity="0.8"/>

                  \x3c!-- 残缺的六芒星阵 --\x3e
                  <polygon points="500,220 742,640 258,640" fill="none" stroke="#b91c1c" stroke-width="2" stroke-dasharray="100 50 200 80" opacity="0.5"/>
                  <polygon points="500,780 742,360 258,360" fill="none" stroke="#b91c1c" stroke-width="2" stroke-dasharray="150 30 50 120" opacity="0.5"/>

                  \x3c!-- 散落在四周的微小血色符文光点 --\x3e
                  <circle cx="300" cy="250" r="2" fill="#f87171" filter="blur(1px)"/>
                  <circle cx="750" cy="380" r="3" fill="#ef4444" filter="blur(1px)"/>
                  <circle cx="250" cy="600" r="1.5" fill="#fca5a5"/>
                  <circle cx="680" cy="750" r="2.5" fill="#f87171" filter="blur(1px)"/>

                  \x3c!-- ================= 6. 核心：不灭的血色晶体 (生命力与能量的凝结) ================= --\x3e
                  \x3c!-- 晶体散发出的巨大能量光晕 --\x3e
                  <circle cx="500" cy="500" r="150" fill="url(#blood-mist-${e})" />
                  <circle cx="500" cy="500" r="80" fill="#dc2626" opacity="0.2" filter="blur(15px)"/>

                  \x3c!-- 悬浮晶体向下的深渊投影 --\x3e
                  <polygon points="480,620 550,700 450,700" fill="#000" opacity="0.6" filter="blur(6px)"/>

                  \x3c!-- 血晶主体 (菱形八面体结构) --\x3e
                  <g filter="drop-shadow(0px 0px 20px rgba(220, 38, 38, 0.8))">
                    \x3c!-- 左侧暗面 --\x3e
                    <polygon points="500,350 500,600 450,500" fill="#991b1b"/>
                    \x3c!-- 右侧受光面 --\x3e
                    <polygon points="500,350 550,500 500,600" fill="url(#blood-crystal-${e})"/>
                    \x3c!-- 顶部切面反光 --\x3e
                    <polygon points="500,350 520,400 480,400" fill="#fecaca" opacity="0.8"/>
                    \x3c!-- 晶体内部的能量核心线 --\x3e
                    <line x1="500" y1="350" x2="500" y2="600" stroke="#fca5a5" stroke-width="2" opacity="0.9"/>
                    <line x1="450" y1="500" x2="550" y2="500" stroke="#f87171" stroke-width="1.5" opacity="0.7"/>
                  </g>

                  \x3c!-- 围绕晶体缓缓旋转的碎石和血光 (动态静止感) --\x3e
                  <circle cx="430" cy="450" r="4" fill="#fca5a5" opacity="0.9"/>
                  <circle cx="570" cy="540" r="3" fill="#ef4444" opacity="0.8"/>
                  <circle cx="520" cy="320" r="2" fill="#f87171" opacity="0.7"/>
                  <polygon points="400,520 415,530 405,540" fill="#18181b" stroke="#ef4444" stroke-width="0.5"/>
                  <polygon points="580,420 590,410 595,425" fill="#18181b" stroke="#ef4444" stroke-width="0.5"/>

                </svg>
              `;case"marketplace":return`
                <svg class="map-svg-bg" viewBox="0 0 1000 1000" preserveAspectRatio="xMidYMid slice">
                  <defs>
                    \x3c!-- 印象派画风：整个坊市是一张巨大的、被暖光与冷夜交替渲染的画布 --\x3e

                    \x3c!-- 底色：深邃的夜空与青石板融合的模糊紫蓝色调 --\x3e
                    <radialGradient id="market-base-${e}" cx="50%" cy="50%" r="70%">
                      <stop offset="0%" stop-color="#312e81" stop-opacity="0.8"/>    \x3c!-- 靛蓝晕染 --\x3e
                      <stop offset="50%" stop-color="#1e1b4b" stop-opacity="0.95"/>   \x3c!-- 深紫罗兰夜色 --\x3e
                      <stop offset="100%" stop-color="#020617" stop-opacity="1"/>     \x3c!-- 画布边缘的暗场 --\x3e
                    </radialGradient>

                    \x3c!-- 油画笔触色块：灯笼投射在地面的大片琥珀色光晕 (湿壁画感) --\x3e
                    <radialGradient id="puddle-amber-${e}" cx="50%" cy="50%" r="50%">
                      <stop offset="0%" stop-color="#d97706" stop-opacity="0.6"/>
                      <stop offset="50%" stop-color="#b45309" stop-opacity="0.3"/>
                      <stop offset="100%" stop-color="#78350f" stop-opacity="0"/>
                    </radialGradient>

                    \x3c!-- 油画笔触色块：灵物摊位散发的冷青色/紫红色魔幻光晕 --\x3e
                    <radialGradient id="puddle-cyan-${e}" cx="50%" cy="50%" r="50%">
                      <stop offset="0%" stop-color="#0d9488" stop-opacity="0.7"/>
                      <stop offset="60%" stop-color="#115e59" stop-opacity="0.2"/>
                      <stop offset="100%" stop-color="#0f172a" stop-opacity="0"/>
                    </radialGradient>

                    <radialGradient id="puddle-magenta-${e}" cx="50%" cy="50%" r="50%">
                      <stop offset="0%" stop-color="#9d174d" stop-opacity="0.6"/>
                      <stop offset="60%" stop-color="#701a75" stop-opacity="0.2"/>
                      <stop offset="100%" stop-color="#2e1065" stop-opacity="0"/>
                    </radialGradient>

                    \x3c!-- 摊位顶棚的渐变色块 (取代线条，用颜色的堆叠表现体积) --\x3e
                    <linearGradient id="tent-warm-${e}" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" stop-color="#991b1b" stop-opacity="0.9"/>
                      <stop offset="100%" stop-color="#450a0a" stop-opacity="0.9"/>
                    </linearGradient>

                    <linearGradient id="tent-cool-${e}" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" stop-color="#0f766e" stop-opacity="0.9"/>
                      <stop offset="100%" stop-color="#042f2e" stop-opacity="0.9"/>
                    </linearGradient>
                  </defs>

                  \x3c!-- 1. 铺底画布：没有边界的夜色 --\x3e
                  <rect width="1000" height="1000" fill="url(#market-base-${e})" />

                  \x3c!-- 2. 大面积的光晕底色涂抹 (Sfumato 晕染技法) 
                       在黑夜中抹上大块的暖色和冷色，确立坊市“熙熙攘攘但模糊”的氛围基调 --\x3e
                  <circle cx="300" cy="700" r="350" fill="url(#puddle-amber-${e})" filter="blur(30px)"/>
                  <circle cx="700" cy="300" r="400" fill="url(#puddle-cyan-${e})" filter="blur(40px)"/>
                  <circle cx="800" cy="800" r="300" fill="url(#puddle-magenta-${e})" filter="blur(35px)"/>
                  <circle cx="200" cy="200" r="250" fill="url(#puddle-amber-${e})" filter="blur(25px)"/>

                  \x3c!-- 3. 色块堆叠：街道/小径的印象 (用不规则的多边形重叠，模拟凹凸不平的青石板反光) --\x3e
                  \x3c!-- 没有任何 stroke，全靠相邻色块的明暗对比 --\x3e
                  <polygon points="100,1000 400,600 500,400 800,0 1000,0 800,500 500,800 300,1000" fill="#312e81" opacity="0.3" filter="blur(5px)"/>
                  <polygon points="150,1000 420,650 520,450 780,0 850,0 750,450 450,750 200,1000" fill="#4338ca" opacity="0.2" filter="blur(2px)"/>
                  <polygon points="250,1000 480,700 550,500 850,50 900,100 800,550 500,850 350,1000" fill="#d97706" opacity="0.1" filter="blur(8px)"/>

                  \x3c!-- 4. 色块堆叠：摊位与建筑的几何印象 (Impasto 厚涂感) --\x3e

                  \x3c!-- 左下角的红色暖光大摊位 (也许是卖符箓或法器的) --\x3e
                  <g>
                    \x3c!-- 摊位的深渊投影 --\x3e
                    <polygon points="0,550 350,450 450,750 0,900" fill="#020617" opacity="0.8" filter="blur(10px)"/>
                    \x3c!-- 顶棚色块 (大面积的深红到暗红渐变) --\x3e
                    <polygon points="-50,500 300,400 380,600 -50,750" fill="url(#tent-warm-${e})"/>
                    \x3c!-- 顶棚受光面 (高光色块，制造立体感) --\x3e
                    <polygon points="-50,500 300,400 250,450 -50,550" fill="#b91c1c" opacity="0.7"/>
                    \x3c!-- 摊位桌面的反光色块 --\x3e
                    <polygon points="50,700 300,600 350,750 100,850" fill="#78350f" opacity="0.9"/>
                    <polygon points="100,720 280,630 300,700 120,780" fill="#b45309" opacity="0.6" filter="blur(2px)"/>
                  </g>

                  \x3c!-- 右上角的青色冷光摊位 (也许是卖灵草或古卷的) --\x3e
                  <g>
                    \x3c!-- 阴影底色 --\x3e
                    <polygon points="600,0 1000,0 1000,400 700,450" fill="#020617" opacity="0.8" filter="blur(10px)"/>
                    \x3c!-- 顶棚色块 --\x3e
                    <polygon points="650,-50 1050,-50 1050,300 750,350" fill="url(#tent-cool-${e})"/>
                    \x3c!-- 顶棚高光色块 --\x3e
                    <polygon points="650,-50 1050,-50 1000,50 680,50" fill="#0d9488" opacity="0.6"/>
                    \x3c!-- 桌面反光 --\x3e
                    <polygon points="700,400 950,250 1000,400 750,550" fill="#134e4a" opacity="0.9"/>
                    \x3c!-- 灵草散发的青色光晕 --\x3e
                    <circle cx="850" cy="350" r="60" fill="url(#puddle-cyan-${e})"/>
                    <circle cx="850" cy="350" r="15" fill="#5eead4" filter="blur(4px)"/>
                  </g>

                  \x3c!-- 右下角的紫色神秘摊位 (黑市角落的隐喻) --\x3e
                  <g>
                    \x3c!-- 阴影 --\x3e
                    <polygon points="750,650 1050,550 1050,1050 850,1050" fill="#000" opacity="0.9" filter="blur(15px)"/>
                    <polygon points="800,700 1050,600 1050,900 850,1000" fill="#4a044e" opacity="0.8"/>
                    <polygon points="800,700 1050,600 1000,650 820,750" fill="#86198f" opacity="0.5"/>
                    <circle cx="950" cy="800" r="50" fill="url(#puddle-magenta-${e})"/>
                    <circle cx="920" cy="820" r="10" fill="#f0abfc" filter="blur(3px)"/>
                    <circle cx="980" cy="780" r="8" fill="#e879f9" filter="blur(2px)"/>
                  </g>

                  \x3c!-- 5. 印象派的“人群” (没有清晰的四肢五官，只有被暖光勾勒的色块) --\x3e
                  \x3c!-- 这里的柱状色块代表着流动的修士，他们是坊市氛围的一部分，但不会打扰你 --\x3e
                  <g opacity="0.7">
                    \x3c!-- 街道中央流动的群像印象 --\x3e
                    <rect x="450" y="450" width="40" height="90" rx="20" fill="#1e1b4b" filter="blur(3px)"/>
                    <rect x="460" y="460" width="15" height="50" rx="7" fill="#f59e0b" opacity="0.4" filter="blur(4px)"/> \x3c!-- 侧面受光面 --\x3e

                    <rect x="520" y="380" width="30" height="70" rx="15" fill="#312e81" filter="blur(4px)"/>
                    <rect x="525" y="390" width="10" height="30" rx="5" fill="#0d9488" opacity="0.5" filter="blur(3px)"/>

                    <rect x="380" y="600" width="45" height="100" rx="22" fill="#0f172a" filter="blur(5px)"/>
                    <rect x="390" y="610" width="15" height="60" rx="7" fill="#b91c1c" opacity="0.3" filter="blur(5px)"/>

                    <rect x="600" y="550" width="35" height="85" rx="17" fill="#2e1065" filter="blur(4px)"/>
                    <rect x="615" y="560" width="15" height="40" rx="7" fill="#d946ef" opacity="0.4" filter="blur(4px)"/>
                  </g>

                  \x3c!-- 6. 提亮的光源点缀 (代表空中的漂浮法灯、灯笼，油画的高光点) --\x3e
                  <g>
                    \x3c!-- 暖黄色高光色点 --\x3e
                    <circle cx="350" cy="400" r="8" fill="#fde047" filter="blur(1px)"/>
                    <circle cx="350" cy="400" r="25" fill="#eab308" opacity="0.4" filter="blur(8px)"/>

                    <circle cx="280" cy="550" r="6" fill="#fcd34d" filter="blur(1px)"/>
                    <circle cx="280" cy="550" r="20" fill="#d97706" opacity="0.5" filter="blur(6px)"/>

                    <circle cx="680" cy="180" r="10" fill="#fef08a" filter="blur(2px)"/>
                    <circle cx="680" cy="180" r="30" fill="#ca8a04" opacity="0.3" filter="blur(10px)"/>

                    \x3c!-- 远处的零星冷色灯火 (增加画面的透视深度) --\x3e
                    <circle cx="650" cy="300" r="3" fill="#67e8f9" opacity="0.8"/>
                    <circle cx="700" cy="250" r="2" fill="#a78bfa" opacity="0.7"/>
                    <circle cx="750" cy="320" r="4" fill="#93c5fd" opacity="0.6"/>
                  </g>

                  \x3c!-- 7. 构图的前景虚化 (Vignette 效果，仿佛你站在一个暗巷的转角往外看，极具安全感) --\x3e
                  \x3c!-- 左上角遮挡暗块 --\x3e
                  <polygon points="0,0 250,0 0,300" fill="#020617" opacity="0.9" filter="blur(15px)"/>
                  <polygon points="0,0 150,0 0,200" fill="#000000" opacity="1" filter="blur(5px)"/>

                  \x3c!-- 右下角遮挡暗块 --\x3e
                  <polygon points="1000,1000 650,1000 1000,700" fill="#020617" opacity="0.9" filter="blur(20px)"/>
                  <polygon points="1000,1000 800,1000 1000,850" fill="#000000" opacity="1" filter="blur(8px)"/>

                </svg>
              `;case"tavern":return`
                <svg class="map-svg-bg" viewBox="0 0 1000 1000" preserveAspectRatio="xMidYMid slice">
                  <defs>
                    \x3c!-- 客栈温暖的室内底光 (原木暗色到中心暖光) --\x3e
                    <radialGradient id="tavern-ambient-${e}" cx="50%" cy="50%" r="75%">
                      <stop offset="0%" stop-color="#3e2723" stop-opacity="1"/>     \x3c!-- 暖木色 --\x3e
                      <stop offset="60%" stop-color="#2a1a16" stop-opacity="0.95"/>  \x3c!-- 暗木色 --\x3e
                      <stop offset="100%" stop-color="#140c0a" stop-opacity="1"/>    \x3c!-- 幽暗角落 --\x3e
                    </radialGradient>

                    \x3c!-- 灯笼散发出的琥珀色温馨光晕 --\x3e
                    <radialGradient id="lantern-glow-${e}" cx="50%" cy="50%" r="50%">
                      <stop offset="0%" stop-color="#ffb300" stop-opacity="0.6"/>    \x3c!-- 明黄 --\x3e
                      <stop offset="30%" stop-color="#fb8c00" stop-opacity="0.3"/>   \x3c!-- 暖橙 --\x3e
                      <stop offset="100%" stop-color="#e65100" stop-opacity="0"/>
                    </radialGradient>

                    \x3c!-- 柜台与八仙桌的厚重木材质感 --\x3e
                    <linearGradient id="heavy-wood-${e}" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" stop-color="#4e342e"/>
                      <stop offset="50%" stop-color="#3e2723"/>
                      <stop offset="100%" stop-color="#2a1a16"/>
                    </linearGradient>

                    \x3c!-- 模板：客栈经典的“八仙桌”与四方长条凳 (可复用) --\x3e
                    <g id="tavern-table-${e}">
                      \x3c!-- 铺着暗红色桌布的八仙桌 --\x3e
                      <rect x="-40" y="-40" width="80" height="80" rx="4" fill="url(#heavy-wood-${e})" stroke="#21120c" stroke-width="3"/>
                      <rect x="-30" y="-30" width="60" height="60" rx="2" fill="#8c2323" opacity="0.8"/> \x3c!-- 暗红桌布 --\x3e

                      \x3c!-- 四面摆放的长条木板凳 --\x3e
                      <rect x="-25" y="-60" width="50" height="12" rx="2" fill="#4e342e" stroke="#21120c" stroke-width="2"/> \x3c!-- 上 --\x3e
                      <rect x="-25" y="48" width="50" height="12" rx="2" fill="#4e342e" stroke="#21120c" stroke-width="2"/>  \x3c!-- 下 --\x3e
                      <rect x="-60" y="-25" width="12" height="50" rx="2" fill="#4e342e" stroke="#21120c" stroke-width="2"/> \x3c!-- 左 --\x3e
                      <rect x="48" y="-25" width="12" height="50" rx="2" fill="#4e342e" stroke="#21120c" stroke-width="2"/>  \x3c!-- 右 --\x3e

                      \x3c!-- 桌上的零散碗碟酒壶 (营造烟火气) --\x3e
                      <circle cx="-10" cy="-10" r="6" fill="#b0bec5"/> \x3c!-- 粗瓷酒壶 --\x3e
                      <circle cx="12" cy="-5" r="3" fill="#cfd8dc"/>   \x3c!-- 酒杯 --\x3e
                      <circle cx="-5" cy="15" r="3" fill="#cfd8dc"/>   \x3c!-- 酒杯 --\x3e
                      <circle cx="10" cy="12" r="7" fill="#8d6e63"/>   \x3c!-- 一碟小菜 --\x3e
                    </g>
                  </defs>

                  \x3c!-- 温暖厚重的原木地板底色 --\x3e
                  <rect width="1000" height="1000" fill="url(#tavern-ambient-${e})" />

                  \x3c!-- ================= 铺设木地板的拼缝线 (增加空间透视感与踏实感) ================= --\x3e
                  <g stroke="#1a100b" stroke-width="3" opacity="0.6">
                    <line x1="100" y1="0" x2="100" y2="1000"/>
                    <line x1="200" y1="0" x2="200" y2="1000"/>
                    <line x1="300" y1="0" x2="300" y2="1000"/>
                    <line x1="400" y1="0" x2="400" y2="1000"/>
                    <line x1="500" y1="0" x2="500" y2="1000"/>
                    <line x1="600" y1="0" x2="600" y2="1000"/>
                    <line x1="700" y1="0" x2="700" y2="1000"/>
                    <line x1="800" y1="0" x2="800" y2="1000"/>
                    <line x1="900" y1="0" x2="900" y2="1000"/>

                    \x3c!-- 横向错落的木板接缝 --\x3e
                    <line x1="0" y1="150" x2="100" y2="150"/><line x1="200" y1="250" x2="300" y2="250"/>
                    <line x1="400" y1="180" x2="500" y2="180"/><line x1="600" y1="320" x2="700" y2="320"/>
                    <line x1="100" y1="450" x2="200" y2="450"/><line x1="300" y1="550" x2="400" y2="550"/>
                    <line x1="700" y1="500" x2="800" y2="500"/><line x1="800" y1="750" x2="900" y2="750"/>
                    <line x1="500" y1="800" x2="600" y2="800"/><line x1="200" y1="850" x2="300" y2="850"/>
                  </g>

                  \x3c!-- ================= 右上角：喧嚣核心的掌柜柜台与酒坛 ================= --\x3e
                  \x3c!-- 柜台后方的阴影区 --\x3e
                  <rect x="750" y="0" width="250" height="400" fill="#1a100b" opacity="0.8"/>

                  \x3c!-- L型实木高柜台 --\x3e
                  <path d="M 750 0 L 750 350 L 1000 350 L 1000 280 L 820 280 L 820 0 Z" fill="url(#heavy-wood-${e})" stroke="#21120c" stroke-width="4"/>

                  \x3c!-- 柜台上的账本与算盘 --\x3e
